INSERT INTO "chat_messages" VALUES(366,'769254bd-d7aa-43eb-851f-410881662e13','model','Dựa trên tài liệu tham khảo, mức học phí năm học 2024 – 2025 của Trường Đại học Thủy lợi được quy định như sau:

