INSERT INTO "chat_messages" VALUES(415,'5449c714-fda3-4e2d-abbe-aa5b985f0f2b','model','Sinh viên có thể bị giảm một mức xếp loại tốt nghiệp (đối với sinh viên đạt loại xuất sắc hoặc giỏi) trong các trường hợp sau:

