INSERT INTO "chat_messages" VALUES(580,'f8bc8653-92af-4fd4-b533-e81b45329155','model','Tôi xin lỗi, thông tin về điểm chuẩn của khoa Công nghệ thông tin không có trong tài liệu bạn cung cấp. Các tài liệu này quy định về chuẩn đầu ra Công nghệ thông tin cho sinh viên đại học của Trường Đại học Thủy lợi.','{"sources": [" QuyDinh_Ve_CDR_CNTT_Ban_hanh_theo_QD411-06-4-2022.pdf", "QD411_QD_DHTL-Chuan_Dau_Ra_CNTT.pdf"], "kind": "rag"}','2026-03-24 10:40:05.051790');
